set -eu; CAP=/Users/michal/tracker-field-captures/2026-09-13-post-walk-v68; DB=$(find "$CAP" -maxdepth 3 -type f -name 'tracker_database' -print -quit); test -n "$DB"; export TRACKER_FIELD_DB="$DB"; python3 - <<'PY'
import os, sqlite3, re, statistics, json
con=sqlite3.connect(f"file:{os.environ['TRACKER_FIELD_DB']}?mode=ro",uri=True); con.row_factory=sqlite3.Row
mx=con.execute('select max(timestamp) from signal_samples').fetchone()[0]; start=mx-3*60*60*1000
ts=[int(r[0]) for r in con.execute('select timestamp from follow_me_observations where userMoved=1 and timestamp>=? order by timestamp',(start,))]
segs=[]
if ts:
 a=p=ts[0]
 for x in ts[1:]:
  if x-p>180000: segs.append((a,p)); a=x
  p=x
 segs.append((a,p))
wa,wb=max([s for s in segs if s[1]-s[0]>=300000],key=lambda s:s[1]-s[0]); total=max(1,int((wb-wa)//30000)+1)
rows=list(con.execute('select timestamp,rssi,deviceFingerprint,deviceName,deviceType,beaconType,serviceDataByUuidHex,serviceUuids from signal_samples where timestamp between ? and ? order by timestamp',(wa,wb)))
def entries(s):
 out={}
 if not s:return out
 for part in str(s).split(';'):
  if '=' not in part: continue
  k,v=part.split('=',1); out[k.lower()]=re.sub(r'[^0-9a-fA-F]','',v)
 return out
def val_for(m, needle):
 for k,v in m.items():
  if needle in k.replace('-',''): return v
 return None
fhn=[]; fp=[]
for r in rows:
 m=entries(r['serviceDataByUuidHex']); feaa=val_for(m,'feaa'); fe2c=val_for(m,'fe2c')
 if feaa and len(feaa)>=2 and feaa[:2].lower() in ('40','41'): fhn.append(r)
 if fe2c and len(fe2c)>=6: fp.append((r,fe2c[:6].upper()))
print('WALK_MIN',round((wb-wa)/60000,1),'FHN_SAMPLES',len(fhn),'FAST_PAIR_SAMPLES',len(fp))
# group fast pair model ids and summarize only safe metadata
g={}
for r,mid in fp: g.setdefault(mid,[]).append(r)
for i,(mid,rs) in enumerate(sorted(g.items(),key=lambda kv:len(kv[1]),reverse=True)[:20],1):
 t=[int(r['timestamp']) for r in rs]; rr=[int(r['rssi']) for r in rs]; bins={int((x-wa)//30000) for x in t}
 print('FASTPAIR',json.dumps({'id':f'M{i:02d}','modelId':mid,'samples':len(rs),'coverage':round(len(bins)/total,3),'spanMin':round((max(t)-min(t))/60000,2),'medianRssi':round(statistics.median(rr),1),'name':str(rs[-1]['deviceName'] or ''),'type':str(rs[-1]['deviceType'] or ''),'beacon':str(rs[-1]['beaconType'] or '')},sort_keys=True))
# time-nearest Fast Pair model ids around every FHN observation; aggregate within +/-2 seconds
near={}
for fr in fhn:
 ft=int(fr['timestamp'])
 for r,mid in fp:
  dt=abs(int(r['timestamp'])-ft)
  if dt<=2000:
   near.setdefault(mid,[]).append((dt,int(fr['rssi']),int(r['rssi'])))
for i,(mid,xs) in enumerate(sorted(near.items(),key=lambda kv:len(kv[1]),reverse=True)[:12],1):
 print('FHN_NEAR_FASTPAIR',json.dumps({'id':f'N{i:02d}','modelId':mid,'pairs':len(xs),'medianDtMs':round(statistics.median([x[0] for x in xs]),1),'medianRssiDelta':round(statistics.median([abs(x[1]-x[2]) for x in xs]),1)},sort_keys=True))
PY

